const input = $('Run Input').first().json;
const profileRows = $('Load Bookkeeping Profile').all().map((item) => item.json).filter((row) => row && row.profileId === 'default');
const runRows = $input.all().map((item) => item.json).filter((row) => row && row.runId);
const profile = profileRows[0] ?? null;

const runId = String(input.runId ?? '').trim() || `run-${Date.now()}-auto`;

const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};
// The same number as the guard in 102, and for the same reason: this is the
// authoritative one, because a schedule reaches this workflow directly without
// passing through the chat tool at all.
const DEAD_AFTER = 31;
const otherLive = runRows.some((row) => String(row.status ?? '') === 'running'
  && String(row.runId) !== runId && (minutesSince(row.startedAt) ?? 999) < DEAD_AFTER);

if (otherLive) {
  return [{ json: { runId, ready: false, skip: true, status: 'skipped',
    errorSummary: 'already-running', reportText: '' } }];
}
if (!profile || !profile.organisationName) {
  return [{ json: { runId, ready: false, skip: false, status: 'failed',
    errorSummary: 'no-profile', reportText: 'There is no bookkeeping profile saved yet, so there was nothing to reason from.' } }];
}

// Caps. A review is bounded so it cannot quietly cost a fortune on an account
// with years of history behind it.
const MAX_LINES = 200;
const BATCH_SIZE = 8;
const MAX_RECEIPT_LOOKUPS = 15;

const rawPeriod = String(input.period ?? '').trim();
let fromDate;
const toDate = new Date();
if (/^\d{4}-(0[1-9]|1[0-2])$/.test(rawPeriod)) {
  fromDate = new Date(`${rawPeriod}-01T00:00:00Z`);
} else if (/^\d{1,3}d$/i.test(rawPeriod)) {
  fromDate = new Date(Date.now() - Number(rawPeriod.slice(0, -1)) * 86400000);
} else {
  fromDate = new Date(Date.now() - 90 * 86400000);
}
const iso = (date) => date.toISOString().slice(0, 10);

return [{ json: {
  runId, ready: true, skip: false,
  period: rawPeriod || '90d',
  fromDate: iso(fromDate), toDate: iso(toDate),
  startedAt: new Date().toISOString(),
  maxLines: MAX_LINES, batchSize: BATCH_SIZE, maxReceiptLookups: MAX_RECEIPT_LOOKUPS,
  neverGuessAbove: Number(profile.neverGuessAbove ?? 0),
  profileJson: JSON.stringify({
    organisationName: profile.organisationName ?? '',
    commonSuppliers: profile.commonSuppliers ?? '',
    commonCustomers: profile.commonCustomers ?? '',
    accountCodeNotes: profile.accountCodeNotes ?? '',
    gstTreatmentNotes: profile.gstTreatmentNotes ?? '',
  }),
} }];

const planned = $('Plan Run').first().json;
const tenant = (() => { try { return $('Read Tenant').first().json; } catch { return null; } })();
const source = tenant && tenant.tenantReady === false ? tenant : planned;
return [{ json: { ...source,
  runId: source.runId,
  startedAt: source.startedAt ?? new Date().toISOString(),
  finishedAt: new Date().toISOString(),
  status: source.status ?? 'failed',
  reportText: source.reportText ?? '',
  errorSummary: source.errorSummary ?? '',
  period: source.period ?? '', queueMode: '',
  transactionsRead: 0, transactionsSuggested: 0, highConfidence: 0, needsHumanCount: 0,
  receiptsSearched: 0, receiptsFound: 0, inputTokens: 0, outputTokens: 0 } }];

const planned = $('Plan Run').first().json;
const raw = $input.first().json ?? {};
const orgs = Number(raw.statusCode ?? 0) === 200 && Array.isArray(raw.body) ? raw.body : [];
if (orgs.length === 0) {
  return [{ json: { ...planned, tenantReady: false, status: 'failed',
    errorSummary: 'xero-not-connected',
    reportText: 'I could not reach Xero, so there was nothing to review. Check the Xero (read-only) credential in n8n.' } }];
}
return [{ json: { ...planned, tenantReady: true,
  tenantId: String(orgs[0].tenantId ?? ''), organisationName: String(orgs[0].tenantName ?? '') } }];

const tenant = $('Read Tenant').first().json;
const raw = $input.first().json ?? {};
const accounts = Number(raw.statusCode ?? 0) === 200 ? (raw.body?.Accounts ?? []) : [];
const banks = accounts.filter((account) => String(account.Type ?? '') === 'BANK' && String(account.Status ?? '') === 'ACTIVE');
if (banks.length === 0) return [{ json: { ...tenant, bankAccountId: '', noBankAccounts: true } }];
return banks.map((account) => ({ json: { ...tenant, bankAccountId: String(account.AccountID ?? ''),
  bankAccountName: String(account.Name ?? '') } }));

// Compact SHA-256. The n8n Code sandbox has no crypto module and no top-level
// await, so this is written out by hand and kept synchronous. It has to be a
// real cryptographic hash rather than the FNV trick used for UUIDs elsewhere:
// this one decides whether a payment the user approved is still the payment
// about to be created, so a collision an attacker can craft from transaction
// text would defeat the check.
const sha256Hex = (message) => {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  // UTF-8 encode without TextEncoder, which is also absent from the sandbox.
  const bytes = [];
  for (let i = 0; i < message.length; i += 1) {
    let c = message.charCodeAt(i);
    if (c < 0x80) { bytes.push(c); }
    else if (c < 0x800) { bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63)); }
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < message.length) {
      const c2 = message.charCodeAt(i + 1); i += 1;
      const cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
      bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    } else { bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i -= 1) bytes.push(Math.floor(bitLen / Math.pow(2, i * 8)) & 0xff);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let chunk = 0; chunk < bytes.length; chunk += 64) {
    for (let i = 0; i < 16; i += 1) {
      w[i] = ((bytes[chunk + i * 4] << 24) | (bytes[chunk + i * 4 + 1] << 16)
            | (bytes[chunk + i * 4 + 2] << 8) | bytes[chunk + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 64; i += 1) {
      const s0 = (rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3)) >>> 0;
      const s1 = (rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10)) >>> 0;
      w[i] = (((w[i - 16] + s0) >>> 0) + ((w[i - 7] + s1) >>> 0)) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i += 1) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (hh + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h = [(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  return h.map((x) => x.toString(16).padStart(8, '0')).join('');
};

// The exact payload the user was shown, reduced to one line. Anything that
// would change what lands in Xero belongs in here: if any of it moves between
// the moment they said yes and the moment we create it, the hashes stop
// matching and the row is refused rather than posted unseen.
const payloadStringOf = (row) => [
  String(row.sourceId ?? ''),
  String(row.sourceType ?? ''),
  String(row.bankAccountId ?? ''),
  String(row.direction ?? ''),
  Number(row.amount ?? 0).toFixed(2),
  String(row.currency ?? ''),
  String(row.occurredAt ?? '').slice(0, 10),
  String(row.suggestedContact ?? ''),
  String(row.suggestedContactId ?? ''),
  String(row.suggestedAccountCode ?? ''),
  String(row.suggestedTaxType ?? ''),
  `AI-${String(row.sourceId ?? '').slice(0, 16)}`,
].join('|');
const payloadHashOf = (row) => sha256Hex(payloadStringOf(row));

const planned = $('Read Tenant').first().json;
const readJson = (name) => { try { return $(name).all().map((item) => item.json); } catch { return []; } };
const okBody = (items) => items.filter((row) => Number(row.statusCode ?? 0) === 200).map((row) => row.body ?? {});

const accountsBody = okBody(readJson('Fetch Accounts'))[0] ?? {};
const taxBody = okBody(readJson('Fetch Tax Rates'))[0] ?? {};
const invoiceBodies = okBody(readJson('Fetch Unpaid Invoices'));
const unrecBodies = okBody(readJson('Fetch Unreconciled Transactions'));
const historyBodies = okBody(readJson('Fetch Coding History'));
const statementItems = readJson('Fetch Statement Lines');

const problems = [];
const expectOk = (name, items) => {
  const bad = items.filter((row) => Number(row.statusCode ?? 0) !== 200);
  if (bad.length) problems.push(`${name} did not answer (${bad.map((row) => row.statusCode || 'no response').join(', ')})`);
};
expectOk('the chart of accounts', readJson('Fetch Accounts'));
expectOk('the tax rates', readJson('Fetch Tax Rates'));
expectOk('the unpaid invoices', readJson('Fetch Unpaid Invoices'));
expectOk('the unreconciled transactions', readJson('Fetch Unreconciled Transactions'));

const accounts = (accountsBody.Accounts ?? [])
  .filter((account) => String(account.Status ?? '') === 'ACTIVE' && String(account.Type ?? '') !== 'BANK')
  .map((account) => ({ Code: String(account.Code ?? ''), Name: String(account.Name ?? ''), Type: String(account.Type ?? '') }))
  .filter((account) => account.Code && account.Name)
  .slice(0, 200);
const taxRates = (taxBody.TaxRates ?? [])
  .filter((rate) => String(rate.Status ?? 'ACTIVE') === 'ACTIVE')
  .map((rate) => ({ TaxType: String(rate.TaxType ?? ''), Name: String(rate.Name ?? ''), DisplayTaxRate: Number(rate.DisplayTaxRate ?? 0) }))
  .filter((rate) => rate.TaxType);
const invoices = invoiceBodies.flatMap((body) => body.Invoices ?? [])
  .filter((invoice) => Number(invoice.AmountDue ?? 0) > 0)
  .map((invoice) => ({ InvoiceID: String(invoice.InvoiceID ?? ''), InvoiceNumber: String(invoice.InvoiceNumber ?? ''),
    Type: String(invoice.Type ?? ''), AmountDue: Number(invoice.AmountDue ?? 0),
    ContactName: String(invoice.Contact?.Name ?? ''), Date: String(invoice.DateString ?? invoice.Date ?? '').slice(0, 10),
    DueDate: String(invoice.DueDateString ?? invoice.DueDate ?? '').slice(0, 10) }));
const unreconciled = unrecBodies.flatMap((body) => body.BankTransactions ?? []);
const history = historyBodies.flatMap((body) => body.BankTransactions ?? [])
  .filter((txn) => txn.IsReconciled === true);

// Outcome A2: statement lines come from the BankStatement report, one call per
// bank account. Xero documents that report's columns as Date, Description,
// Reference, Reconciled, Source, Amount, Balance — but the cells are read by
// their header name rather than by position, so a reordered or extra column
// cannot silently shift every value by one. Some organisations render money out
// and money in as separate Spent/Received columns instead of one signed Amount,
// and both shapes are handled.
const HEADER_ALIASES = {
  date: ['date'],
  description: ['description', 'details', 'payee'],
  reference: ['reference', 'ref'],
  reconciled: ['reconciled', 'is reconciled'],
  amount: ['amount'],
  spent: ['spent', 'money out', 'debit', 'withdrawal'],
  received: ['received', 'money in', 'credit', 'deposit'],
};
// Documented order, used only when a report arrives with no header row at all.
const POSITIONAL = ['date', 'description', 'reference', 'reconciled', 'source', 'amount', 'balance'];

const cellText = (cell) => String((cell && typeof cell === 'object' ? cell.Value : cell) ?? '').trim();
const money = (text) => {
  const cleaned = String(text ?? '').replace(/[^0-9.,()-]/g, '').replace(/,/g, '');
  if (cleaned === '') return null;
  // Accounting style: (12.34) means negative.
  const negated = /^\(.*\)$/.test(cleaned);
  const parsed = Number(negated ? cleaned.replace(/[()]/g, '') : cleaned);
  if (!Number.isFinite(parsed)) return null;
  return negated ? -Math.abs(parsed) : parsed;
};

const columnMapOf = (rows) => {
  const header = rows.find((row) => String(row.RowType ?? '') === 'Header');
  if (!header) return null;
  const names = (header.Cells ?? []).map((cell) => cellText(cell).toLowerCase());
  const map = {};
  for (const [key, aliases] of Object.entries(HEADER_ALIASES)) {
    const at = names.findIndex((name) => aliases.includes(name));
    if (at !== -1) map[key] = at;
  }
  return Object.keys(map).length ? map : null;
};

const seen = new Map();
const lines = [];
for (const item of statementItems) {
  if (Number(item.statusCode ?? 0) !== 200) {
    problems.push('one bank account statement did not answer');
    continue;
  }
  const report = (item.body?.Reports ?? [])[0] ?? {};
  const bankAccountId = String(item.bankAccountId ?? report.ReportID ?? '');
  const topRows = report.Rows ?? [];
  const map = columnMapOf(topRows)
    ?? Object.fromEntries(POSITIONAL.map((name, index) => [name, index]));

  const dataRows = topRows.flatMap((section) => section.Rows ?? [])
    .filter((row) => String(row.RowType ?? 'Row') !== 'Header');

  for (const row of dataRows) {
    const cells = row.Cells ?? [];
    const at = (key) => (map[key] === undefined ? '' : cellText(cells[map[key]]));

    // Xero writes Yes/No here. Anything that is not a clear yes is treated as
    // unreconciled, so a blank never quietly hides a line from the review.
    if (/^(yes|true)$/i.test(at('reconciled'))) continue;

    let amount = money(at('amount'));
    if (amount === null) {
      const spent = money(at('spent')) ?? 0;
      const received = money(at('received')) ?? 0;
      if (!spent && !received) continue;
      amount = received > 0 ? Math.abs(received) : -Math.abs(spent);
    }
    if (amount === null || amount === 0) continue;

    const rawDate = at('date');
    const isoDate = /^\d{4}-\d{2}-\d{2}$/.test(rawDate) ? rawDate : rawDate.slice(0, 10);
    const description = at('description');
    const base = sha256Hex([bankAccountId, isoDate, amount.toFixed(2), description].join('|')).slice(0, 24);
    // Two identical lines on one account on one day are told apart by position,
    // which stays stable as long as the report does.
    const ordinal = (seen.get(base) ?? 0);
    seen.set(base, ordinal + 1);

    lines.push({
      sourceType: 'statement-line',
      sourceId: ordinal === 0 ? base : `${base}-${ordinal}`,
      bankAccountId,
      occurredAt: isoDate,
      amount,
      direction: amount < 0 ? 'outflow' : 'inflow',
      currency: String(planned.baseCurrency ?? 'AUD'),
      contactName: '',
      description: description.slice(0, 300),
      reference: at('reference').slice(0, 80),
    });
  }
}

// Whether Xero hands back bank statement lines through the ordinary Accounting
// API is not something this can know in advance: it depends on the
// organisation, its bank feed, and what the report is willing to return. So
// rather than being told which world it is in, the review works it out and says
// so.
//
// With statement lines, it is reconciliation prep: these are the lines still
// sitting in the bank feed, and a transaction created against one is something
// the user can then reconcile.
//
// Without them, it falls back to a coding review over the transactions already
// entered in Xero but not yet reconciled. Those rows already exist, so creating
// anything for them would duplicate them — which is exactly why 108 refuses any
// row whose sourceType is not statement-line. The write lane switches itself
// off in this mode without anything being configured.
let queue = lines;
let queueMode = 'statement-line';

if (queue.length === 0) {
  queueMode = 'coding-review';
  queue = unreconciled.map((txn) => {
    const total = Number(txn.Total ?? 0);
    const isSpend = String(txn.Type ?? '').startsWith('SPEND');
    const amount = isSpend ? -Math.abs(total) : Math.abs(total);
    const occurredAt = String(txn.DateString ?? txn.Date ?? '').slice(0, 10);
    return {
      sourceType: 'bank-transaction',
      sourceId: String(txn.BankTransactionID ?? ''),
      bankAccountId: String(txn.BankAccount?.AccountID ?? ''),
      occurredAt: /^\d{4}-\d{2}-\d{2}$/.test(occurredAt) ? occurredAt : occurredAt.slice(0, 10),
      amount,
      direction: amount < 0 ? 'outflow' : 'inflow',
      currency: String(txn.CurrencyCode ?? planned.baseCurrency ?? 'AUD'),
      contactName: String(txn.Contact?.Name ?? ''),
      description: String((txn.LineItems ?? [])[0]?.Description ?? txn.Reference ?? '').slice(0, 300),
      reference: String(txn.Reference ?? '').slice(0, 80),
    };
  }).filter((row) => row.sourceId && row.amount !== 0);

  if (statementItems.length > 0) {
    problems.push('the bank statement report returned no usable lines, so this was a coding review of the transactions already in Xero rather than of the bank feed');
  }
}

queue.sort((a, b) => (a.occurredAt < b.occurredAt ? 1 : -1));
const capped = queue.slice(0, planned.maxLines);

return [{ json: { ...planned, accounts, taxRates, invoices, unreconciled, history,
  queue: capped, queueMode,
  transactionsRead: queue.length,
  truncated: queue.length > capped.length,
  problems } }];

const normalised = $('Normalise Queue').first().json;
const priorRows = (() => { try { return $('Load Prior Decisions').all().map((item) => item.json); } catch { return []; } })();

// Card descriptors are noise. What is left after stripping the payment-rail
// words and the digits is close enough to a merchant name to group on.
const STOP = new Set(['pty','ltd','pl','the','and','au','aus','com','inc','co','visa','eftpos','tfr','dd',
  'card','purchase','payment','pos','sq','sp','paypal','stripe','www','http','https','help','xx']);
const tokensOf = (text) => String(text ?? '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/)
  .filter((token) => token.length >= 3 && !STOP.has(token) && !/^\d+$/.test(token));
// Deduped, because a descriptor repeats the merchant name as often as not
// (UBER *TRIP HELP.UBER.COM), and 'uber trip uber' would never match the
// 'uber trip' that the same merchant produces in Xero's own contact name.
const merchantKey = (text) => Array.from(new Set(tokensOf(text))).slice(0, 3).join(' ');

// Amounts are compared as cents, as strings. Float arithmetic on money finds
// matches that are not there and misses ones that are.
const cents = (value) => Math.abs(Number(value ?? 0)).toFixed(2);

// A whole token, never a substring: INV-0008 matches INV0008 but not XINV00081.
const referenceAppears = (needle, haystack) => {
  const clean = String(needle ?? '').replace(/[^A-Za-z0-9]/g, '');
  if (clean.length < 4) return false;
  const flat = String(haystack ?? '').replace(/[^A-Za-z0-9]/g, '');
  const index = flat.toUpperCase().indexOf(clean.toUpperCase());
  if (index === -1) return false;
  const before = flat[index - 1];
  const after = flat[index + clean.length];
  return !(before && /[A-Za-z0-9]/.test(before) && /[0-9]/.test(clean[0]))
    && !(after && /[0-9]/.test(after));
};
const DATE_WINDOW_DAYS = 45;
const daysApart = (a, b) => {
  const first = Date.parse(`${a}T00:00:00Z`);
  const second = Date.parse(`${b}T00:00:00Z`);
  if (Number.isNaN(first) || Number.isNaN(second)) return 9999;
  return Math.abs(first - second) / 86400000;
};

// 1. What the user has already told us, which outranks everything inferred.
const userTuples = new Map();
for (const row of priorRows) {
  if (!['accepted', 'changed'].includes(String(row.userDecision ?? ''))) continue;
  const key = merchantKey(row.description || row.contactName);
  if (!key) continue;
  const code = String(row.userAccountCode || row.suggestedAccountCode || '');
  const tax = String(row.suggestedTaxType ?? '');
  if (!code) continue;
  const existing = userTuples.get(key);
  if (existing && (existing.code !== code || existing.tax !== tax)) { existing.conflict = true; continue; }
  if (!existing) userTuples.set(key, { code, tax, conflict: false });
}

// 4. How this organisation has coded the same merchant before. Account and tax
// only: history can never say who this payment was to.
const historyTuples = new Map();
for (const txn of normalised.history) {
  const key = merchantKey(txn.Contact?.Name || txn.Reference);
  const line = (txn.LineItems ?? [])[0];
  if (!key || !line) continue;
  const code = String(line.AccountCode ?? '');
  const tax = String(line.TaxType ?? '');
  if (!code) continue;
  const existing = historyTuples.get(key) ?? { code, tax, count: 0, conflict: false };
  if (existing.code !== code || existing.tax !== tax) existing.conflict = true;
  existing.count += 1;
  historyTuples.set(key, existing);
}

const accountName = new Map(normalised.accounts.map((account) => [account.Code, account.Name]));
const settled = [];
const uncertain = [];
const shortlists = {};
const contactLists = {};

for (const line of normalised.queue) {
  const key = merchantKey(line.description || line.contactName);
  const base = { ...line, suggestedContact: '', suggestedContactId: '', suggestedAccountCode: '',
    suggestedAccountName: '', suggestedTaxType: '', matchedInvoiceId: '', matchedInvoiceNumber: '',
    identityConfidence: 0, accountingConfidence: 0, documentConfidence: 0,
    basis: '', needsHuman: 'yes', whatToCheck: '' };

  // 2. An exact invoice: the amount to the cent, plus either its number
  // appearing as a whole token or the vendor's own name, in a sane window and
  // in the right direction. Amount alone is never enough.
  const invoiceHits = normalised.invoices.filter((invoice) => {
    if (cents(invoice.AmountDue) !== cents(line.amount)) return false;
    if (invoice.Type === 'ACCREC' && line.direction !== 'inflow') return false;
    if (invoice.Type === 'ACCPAY' && line.direction !== 'outflow') return false;
    const text = `${line.description} ${line.reference}`;
    const byNumber = referenceAppears(invoice.InvoiceNumber, text);
    const vendorTokens = tokensOf(invoice.ContactName);
    const lineTokens = new Set(tokensOf(text));
    const byVendor = vendorTokens.some((token) => lineTokens.has(token));
    if (!byNumber && !byVendor) return false;
    const withinWindow = [invoice.Date, invoice.DueDate].some((date) => date && daysApart(line.occurredAt, date) <= DATE_WINDOW_DAYS);
    return withinWindow;
  });
  shortlists[line.sourceId] = invoiceHits.slice(0, 5);

  if (invoiceHits.length === 1) {
    settled.push({ ...base, suggestedContact: invoiceHits[0].ContactName,
      matchedInvoiceId: invoiceHits[0].InvoiceID, matchedInvoiceNumber: invoiceHits[0].InvoiceNumber,
      identityConfidence: 1, accountingConfidence: 1, documentConfidence: 1,
      basis: 'exact-invoice', needsHuman: 'no',
      whatToCheck: `This looks like invoice ${invoiceHits[0].InvoiceNumber}. Open Find and Match in Xero and tick it.` });
    continue;
  }
  if (invoiceHits.length > 1) {
    settled.push({ ...base, basis: 'conflicting-invoices', needsHuman: 'yes',
      whatToCheck: `I found more than one invoice this payment could be. Which one is right: ${invoiceHits.slice(0, 3).map((invoice) => invoice.InvoiceNumber).join(', ')}?` });
    continue;
  }

  // 3. Something already entered in Xero that this line pays for.
  const existing = normalised.unreconciled.find((txn) =>
    cents(txn.Total) === cents(line.amount)
    && daysApart(line.occurredAt, String(txn.DateString ?? txn.Date ?? '').slice(0, 10)) <= 3);
  if (existing) {
    settled.push({ ...base, suggestedContact: String(existing.Contact?.Name ?? ''),
      identityConfidence: 0.9, accountingConfidence: 0.9, documentConfidence: 0,
      basis: 'existing-match', needsHuman: 'no',
      whatToCheck: 'You have already entered this one in Xero, so it should show as a green match. Click OK on it.' });
    continue;
  }

  const userRule = key ? userTuples.get(key) : null;
  const historyRule = key ? historyTuples.get(key) : null;

  if (userRule && !userRule.conflict && accountName.has(userRule.code)) {
    settled.push({ ...base, suggestedContact: line.contactName || '',
      suggestedAccountCode: userRule.code, suggestedAccountName: accountName.get(userRule.code),
      suggestedTaxType: userRule.tax,
      identityConfidence: 0.85, accountingConfidence: 0.98, documentConfidence: 0,
      basis: 'user-rule', needsHuman: 'no',
      whatToCheck: '' });
    continue;
  }
  if (historyRule && !historyRule.conflict && historyRule.count >= 2 && accountName.has(historyRule.code)) {
    settled.push({ ...base, suggestedContact: line.contactName || '',
      suggestedAccountCode: historyRule.code, suggestedAccountName: accountName.get(historyRule.code),
      suggestedTaxType: historyRule.tax,
      // History fixes the account, never the identity. Identity stays capped
      // below the bar on purpose, so a name-only guess cannot be acted on.
      identityConfidence: 0.85, accountingConfidence: 0.95, documentConfidence: 0,
      basis: 'history-unanimous', needsHuman: 'no', whatToCheck: '' });
    continue;
  }
  if (historyRule && historyRule.conflict) {
    settled.push({ ...base, basis: 'history-conflict', needsHuman: 'yes',
      whatToCheck: 'You have coded this supplier more than one way before, so I did not want to guess which is right this time.' });
    continue;
  }

  contactLists[line.sourceId] = [];
  uncertain.push(line);
}

return [{ json: { ...normalised, settled, uncertain, shortlists, contactLists,
  anyUncertain: uncertain.length > 0 } }];

const prepassed = $('Deterministic Pre-Pass').first().json;
const size = prepassed.batchSize;
const perBatchReceipts = Math.max(0, Math.floor(prepassed.maxReceiptLookups / Math.max(1, Math.ceil(prepassed.uncertain.length / size))));
const batches = [];
for (let i = 0; i < prepassed.uncertain.length; i += size) batches.push(prepassed.uncertain.slice(i, i + size));

return batches.map((batch) => {
  const ids = batch.map((txn) => txn.sourceId);
  const pick = (source) => Object.fromEntries(ids.map((id) => [id, source[id] ?? []]));
  return { json: {
    runId: prepassed.runId,
    batchJson: JSON.stringify(batch),
    catalogJson: JSON.stringify(prepassed.accounts),
    taxJson: JSON.stringify(prepassed.taxRates),
    invoiceShortlistJson: JSON.stringify(pick(prepassed.shortlists)),
    contactShortlistJson: JSON.stringify(pick(prepassed.contactLists)),
    historyJson: JSON.stringify({}),
    profileJson: prepassed.profileJson,
    memorySummary: String(prepassed.memorySummary ?? ''),
    gmailConnected: String(prepassed.gmailConnected === true),
    receiptBudget: String(perBatchReceipts),
  } };
});

// Compact SHA-256. The n8n Code sandbox has no crypto module and no top-level
// await, so this is written out by hand and kept synchronous. It has to be a
// real cryptographic hash rather than the FNV trick used for UUIDs elsewhere:
// this one decides whether a payment the user approved is still the payment
// about to be created, so a collision an attacker can craft from transaction
// text would defeat the check.
const sha256Hex = (message) => {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  // UTF-8 encode without TextEncoder, which is also absent from the sandbox.
  const bytes = [];
  for (let i = 0; i < message.length; i += 1) {
    let c = message.charCodeAt(i);
    if (c < 0x80) { bytes.push(c); }
    else if (c < 0x800) { bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63)); }
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < message.length) {
      const c2 = message.charCodeAt(i + 1); i += 1;
      const cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
      bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    } else { bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i -= 1) bytes.push(Math.floor(bitLen / Math.pow(2, i * 8)) & 0xff);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let chunk = 0; chunk < bytes.length; chunk += 64) {
    for (let i = 0; i < 16; i += 1) {
      w[i] = ((bytes[chunk + i * 4] << 24) | (bytes[chunk + i * 4 + 1] << 16)
            | (bytes[chunk + i * 4 + 2] << 8) | bytes[chunk + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 64; i += 1) {
      const s0 = (rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3)) >>> 0;
      const s1 = (rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10)) >>> 0;
      w[i] = (((w[i - 16] + s0) >>> 0) + ((w[i - 7] + s1) >>> 0)) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i += 1) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (hh + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h = [(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  return h.map((x) => x.toString(16).padStart(8, '0')).join('');
};

// The exact payload the user was shown, reduced to one line. Anything that
// would change what lands in Xero belongs in here: if any of it moves between
// the moment they said yes and the moment we create it, the hashes stop
// matching and the row is refused rather than posted unseen.
const payloadStringOf = (row) => [
  String(row.sourceId ?? ''),
  String(row.sourceType ?? ''),
  String(row.bankAccountId ?? ''),
  String(row.direction ?? ''),
  Number(row.amount ?? 0).toFixed(2),
  String(row.currency ?? ''),
  String(row.occurredAt ?? '').slice(0, 10),
  String(row.suggestedContact ?? ''),
  String(row.suggestedContactId ?? ''),
  String(row.suggestedAccountCode ?? ''),
  String(row.suggestedTaxType ?? ''),
  `AI-${String(row.sourceId ?? '').slice(0, 16)}`,
].join('|');
const payloadHashOf = (row) => sha256Hex(payloadStringOf(row));

const prepassed = $('Deterministic Pre-Pass').first().json;
const batchResults = (() => { try { return $('Run Matching Batch').all().map((item) => item.json); } catch { return []; } })();

const byId = new Map(prepassed.uncertain.map((txn) => [txn.sourceId, txn]));
const problems = [...(prepassed.problems ?? [])];
let inputTokens = 0;
let outputTokens = 0;
let receiptsSearched = 0;
let receiptsFound = 0;

const modelRows = [];
for (const result of batchResults) {
  inputTokens += Number(result.inputTokens ?? 0);
  outputTokens += Number(result.outputTokens ?? 0);
  receiptsSearched += Number(result.receiptsSearched ?? 0);
  receiptsFound += Number(result.receiptsFound ?? 0);
  if (result.ok === false) { problems.push(String(result.error ?? 'a batch failed')); continue; }
  for (const row of result.suggestions ?? []) modelRows.push(row);
}

const merged = [];
for (const row of prepassed.settled) merged.push(row);
for (const row of modelRows) {
  const txn = byId.get(row.sourceId);
  if (!txn) continue;
  merged.push({ ...txn, suggestedContact: row.contactName ?? '', suggestedContactId: row.suggestedContactId ?? '',
    suggestedAccountCode: row.suggestedAccountCode ?? '', suggestedAccountName: row.suggestedAccountName ?? '',
    suggestedTaxType: row.suggestedTaxType ?? '', matchedInvoiceId: row.matchedInvoiceId ?? '',
    matchedInvoiceNumber: '', identityConfidence: Number(row.identityConfidence ?? 0),
    accountingConfidence: Number(row.accountingConfidence ?? 0), documentConfidence: Number(row.documentConfidence ?? 0),
    basis: row.basis ?? 'model-only', needsHuman: row.needsHuman === true ? 'yes' : 'no',
    whatToCheck: row.whatToCheck ?? '' });
}
// Anything the model never came back about is not dropped. Fail towards a
// person, never towards silence.
for (const txn of prepassed.uncertain) {
  if (!merged.some((row) => row.sourceId === txn.sourceId)) {
    merged.push({ ...txn, suggestedContact: '', suggestedContactId: '', suggestedAccountCode: '',
      suggestedAccountName: '', suggestedTaxType: '', matchedInvoiceId: '', matchedInvoiceNumber: '',
      identityConfidence: 0, accountingConfidence: 0, documentConfidence: 0,
      basis: 'not-classified', needsHuman: 'yes',
      whatToCheck: 'I did not manage to work this one out. Ask me to run the review again if it matters.' });
  }
}

// The thresholds. Any one of them failing hands the row to a person.
const IDENTITY_FLOOR = 0.80;
const ACCOUNTING_FLOOR = 0.90;
const OVERALL_FLOOR = 0.92;
const threshold = Number(prepassed.neverGuessAbove ?? 0);

const rows = merged.map((row, index) => {
  const confidence = Math.min(Number(row.identityConfidence ?? 0), Number(row.accountingConfidence ?? 0));
  const overThreshold = threshold > 0 && Math.abs(Number(row.amount ?? 0)) > threshold;
  let needsHuman = row.needsHuman === 'yes'
    || confidence < OVERALL_FLOOR
    || Number(row.identityConfidence ?? 0) < IDENTITY_FLOOR
    || Number(row.accountingConfidence ?? 0) < ACCOUNTING_FLOOR
    || overThreshold;
  // An invoice match or a transaction already in Xero is a job for the user
  // inside Xero, not a gap in the reasoning, so it is not flagged as one.
  if (['exact-invoice', 'existing-match'].includes(row.basis)) needsHuman = false;

  let whatToCheck = row.whatToCheck ?? '';
  if (needsHuman && overThreshold && !whatToCheck) {
    whatToCheck = `This is above the $${threshold} you asked me to always check with you, so I have not suggested a code.`;
  }
  if (needsHuman && !whatToCheck) whatToCheck = 'I could not confidently identify who this payment was for.';

  const out = { ...row, confidence, needsHuman: needsHuman ? 'yes' : 'no', whatToCheck };
  if (needsHuman && !['exact-invoice', 'existing-match'].includes(row.basis)) {
    out.suggestedAccountCode = '';
    out.suggestedAccountName = '';
    out.suggestedTaxType = '';
  }
  return { ...out,
    suggestionId: `sug-${prepassed.runId}-${index + 1}`,
    runId: prepassed.runId,
    payloadHash: payloadHashOf(out),
    acceptedHash: '', userDecision: '', userAccountCode: '', decidedAt: '',
    executionStatus: '', xeroBankTransactionId: '', executedAt: '', executionError: '',
    receiptJson: '' };
});

const needsHumanCount = rows.filter((row) => row.needsHuman === 'yes').length;
return [{ json: { ...prepassed, rows,
  transactionsSuggested: rows.length,
  needsHumanCount,
  highConfidence: rows.length - needsHumanCount,
  inputTokens, outputTokens, receiptsSearched, receiptsFound,
  problems,
  status: problems.length ? 'partial' : 'completed' } }];

const merged = $('Merge All Suggestions').first().json;
const rows = merged.rows ?? [];

const money = (row) => {
  const value = Number(row.amount ?? 0);
  return `${value < 0 ? '-' : ''}$${Math.abs(value).toFixed(2)}`;
};
const who = (row) => String(row.contactName || row.suggestedContact || row.description || 'unnamed').slice(0, 50);
const head = (row) => `${String(row.occurredAt ?? '').slice(0, 10)}  ${money(row)}  ${who(row)}`;

const WHY = {
  'user-rule': 'it follows a rule you already gave me',
  'history-unanimous': 'every past payment to them was coded there',
  'model-only': 'the description and your chart of accounts point that way',
  'receipt-supported': 'the receipt in your mailbox supports it',
};

const ready = rows.filter((row) => row.needsHuman === 'no' && !['exact-invoice', 'existing-match'].includes(row.basis));
const match = rows.filter((row) => ['exact-invoice', 'existing-match'].includes(row.basis));
const uncertain = rows.filter((row) => row.needsHuman === 'yes');

const lines = [];
lines.push(`I checked ${rows.length} outstanding transaction${rows.length === 1 ? '' : 's'}. I can prepare ${ready.length} now, and I need your help with ${uncertain.length}.`);

if (ready.length) {
  lines.push('');
  lines.push('Ready to prepare:');
  for (const row of ready.slice(0, 40)) {
    const why = WHY[row.basis] ?? 'that is what the evidence points to';
    lines.push(`- ${head(row)}: I think this should be coded to ${row.suggestedAccountCode} ${row.suggestedAccountName}, using ${row.suggestedTaxType}. Why: ${why}.`);
  }
}
if (match.length) {
  lines.push('');
  lines.push('Match these in Xero yourself:');
  for (const row of match.slice(0, 40)) lines.push(`- ${head(row)}: ${row.whatToCheck}`);
}
if (uncertain.length) {
  lines.push('');
  lines.push('I need your help with:');
  for (const row of uncertain.slice(0, 40)) lines.push(`- ${head(row)}: I left this untouched. ${row.whatToCheck}`);
}
if (merged.receiptsSearched) {
  lines.push('');
  lines.push(`I looked in your mailbox for receipts on ${merged.receiptsSearched} of these and found ${merged.receiptsFound}.`);
}
if (merged.truncated) {
  lines.push('');
  lines.push(`There were more than ${merged.maxLines} unreconciled lines, so I looked at the ${merged.maxLines} most recent.`);
}
if ((merged.problems ?? []).length) {
  lines.push('');
  lines.push(`Some of it did not come back cleanly: ${merged.problems.join('; ')}.`);
}
if (merged.queueMode === 'coding-review') {
  lines.push('');
  lines.push('These are transactions already entered in Xero and not yet reconciled, because your bank feed lines were not available through the API. I can suggest how to code them, but I cannot prepare anything for you here: they already exist, and creating them again would double them up.');
}
lines.push('');
lines.push('Nothing here is reconciled. A transaction is reconciled when you click OK in Xero, and not before.');

return [{ json: { ...merged, reportText: lines.join('\n'),
  errorSummary: (merged.problems ?? []).join('; ').slice(0, 900),
  finishedAt: new Date().toISOString() } }];
